// Jank, memory, and the recorded page-turn and first-page times (issue #653,
// gates 2 and 3, and the outcome trace). Opens the bench's 50 MB PDF and its
// large EPUB (generated by the runner into a temporary folder, never
// committed), turns 20 pages in each, searches a word in each, leaves Reader,
// waits 30 s, and reads the heap after a forced GC.
//
// The memory gate is relative to a control visit (control.bench.ts): this spec's
// heap is read as today, and the runner subtracts the control's growth.
//
// Long tasks: a PerformanceObserver('longtask') is installed in the top window
// before any app code (addInitScript, top frame only). Each entry carries its
// attribution; the runner decides which entries are Reader's (see
// scripts/reader-bench-budget.mjs `attributeLongTasks`). The bench records
// every action window, and the number of iframes in the page, so the runner
// can check that iframe attribution isolates the Reader Frame.
import { writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { chooseNextFile, installFilePicker } from "../support/file-picker";
import { tabTo } from "../support/keyboard";
import { expect, test } from "../support/test";
import {
  benchOut,
  documentFrame,
  focusDocument,
  goHome,
  heapAfterGc,
  indicatorText,
  nowIn,
  openReader,
  pageIndicator,
  runHostCommand,
  timedWindow,
  waitFrameChange,
} from "./support";

const PDF = "large-document.pdf";
const EPUB = "large-book.epub";
const TURNS = 20;
/** The quiet period the gate names: 30 s after leaving Reader. */
const LEAVE_SETTLE_MS = 30_000;

/** The PDF's page count and the EPUB's search hits; the runner's fixture makes both. */
const PDF_PAGES = 96;
const PDF_HITS = 4;
const EPUB_HITS = 3;

const LONG_TASK_OBSERVER = `
  if (window.top === window && !window.__readerLongTasks) {
    window.__readerLongTasks = [];
    new PerformanceObserver((list) => {
      for (const entry of list.getEntries()) {
        window.__readerLongTasks.push({
          startMs: entry.startTime,
          durationMs: entry.duration,
          attribution: entry.attribution.map((item) => ({
            containerType: item.containerType,
            containerId: item.containerId,
            containerName: item.containerName,
          })),
        });
      }
    }).observe({ type: "longtask", buffered: true });
  }
`;

test.use({
  plugins: ["maibuk-reader"],
  pluginApprovals: [{ pluginId: "maibuk-reader", granted: ["files:pick"] }],
  builtInPlugins: [{ id: "maibuk-reader" }],
});

test.beforeEach(async ({ page }) => {
  const pdfPath = process.env.READER_BENCH_PDF;
  const epubPath = process.env.READER_BENCH_EPUB;
  if (!pdfPath || !epubPath) throw new Error("READER_BENCH_PDF and READER_BENCH_EPUB are required");
  await installFilePicker(page, [
    { name: PDF, path: pdfPath, type: "application/pdf", served: true },
    { name: EPUB, path: epubPath, type: "application/epub+zip", served: true },
  ]);
  await page.addInitScript(LONG_TASK_OBSERVER);
});

test("open, turn 20 pages, search, leave, and settle the heap: PDF and EPUB", async ({ page }) => {
  const windows: { name: string; startMs: number; endMs: number }[] = [];
  const turnMs = { pdf: [] as number[], epub: [] as number[] };
  const firstPageMs: Record<string, number> = {};
  const searchMs: Record<string, number> = {};

  await page.goto("/");
  await expect(page.getByRole("listbox", { name: "Primary navigation" })).toBeVisible({
    timeout: 60_000,
  });
  // The heap before opening: the app with Reader enabled, never opened.
  const baselineHeapBytes = await heapAfterGc(page);
  await openReader(page);

  // PDF: open by key press, first page, turns, search.
  await tabTo(page, page.getByRole("button", { name: "Open file…", exact: true }), { max: 60 });
  const pdfOpen = await timedWindow(page, windows, "open PDF", async () => {
    await page.keyboard.press("Enter");
    await expect(page).toHaveURL(/\/plugin\/maibuk-reader\/document$/);
    await focusDocument(page);
    await expect(pageIndicator(page)).toContainText(`1 of ${PDF_PAGES}`, { timeout: 120_000 });
  });
  firstPageMs.pdf = pdfOpen.durationMs;
  // Counted with the Document open: the Reader Frame is the iframe under test.
  // Each iframe the page holds, described: the Reader Frame ("Reading") and the
  // Plugin's hidden, inert sandbox host that runs its Worker. The runner checks
  // that every iframe is one of Reader's, which is what makes iframe attribution
  // mean Reader.
  const iframes = await page.evaluate(() =>
    [...document.querySelectorAll("iframe")].map((frame) => ({
      title: frame.getAttribute("title"),
      ariaHidden: frame.getAttribute("aria-hidden"),
      sandbox: frame.getAttribute("sandbox"),
    }))
  );

  await timedWindow(page, windows, "turn 20 pages, PDF", async () => {
    for (let turn = 0; turn < TURNS; turn++) {
      const before = await indicatorText(page);
      const started = await nowIn(page);
      await page.keyboard.press("ArrowRight");
      await waitFrameChange(page, before);
      turnMs.pdf.push((await nowIn(page)) - started);
    }
  });

  const pdfSearch = await timedWindow(page, windows, "search PDF", async () => {
    await runHostCommand(page, "Find in Document");
    const search = documentFrame(page).getByRole("searchbox");
    await expect(search).toBeVisible();
    await search.fill("wanderlust");
    await search.press("Enter");
    await expect(documentFrame(page).locator("#search-status")).toHaveText(
      new RegExp(`^1 of ${PDF_HITS}$`),
      { timeout: 120_000 }
    );
  });
  searchMs.pdf = pdfSearch.durationMs;
  await page.keyboard.press("Escape");

  // EPUB: back to the Shelf, open the second Document, first page, turns, search.
  await runHostCommand(page, "Back to Shelf");
  await expect(page).toHaveURL(/\/plugin\/maibuk-reader\/reader$/);
  await chooseNextFile(page, EPUB);
  await tabTo(page, page.getByRole("button", { name: "Open file…", exact: true }), { max: 60 });
  const epubOpen = await timedWindow(page, windows, "open EPUB", async () => {
    await page.keyboard.press("Enter");
    await expect(page).toHaveURL(/\/plugin\/maibuk-reader\/document$/);
    await focusDocument(page);
    await expect(pageIndicator(page)).toBeVisible({ timeout: 120_000 });
  });
  firstPageMs.epub = epubOpen.durationMs;

  await timedWindow(page, windows, "turn 20 pages, EPUB", async () => {
    for (let turn = 0; turn < TURNS; turn++) {
      const before = await indicatorText(page);
      const started = await nowIn(page);
      await page.keyboard.press("ArrowRight");
      await waitFrameChange(page, before);
      turnMs.epub.push((await nowIn(page)) - started);
    }
  });

  const epubSearch = await timedWindow(page, windows, "search EPUB", async () => {
    await runHostCommand(page, "Find in Document");
    const search = documentFrame(page).getByRole("searchbox");
    await expect(search).toBeVisible();
    await search.fill("wanderlust");
    await search.press("Enter");
    await expect(documentFrame(page).locator("#search-status")).toHaveText(
      new RegExp(`^1 of ${EPUB_HITS}$`),
      { timeout: 120_000 }
    );
  });
  searchMs.epub = epubSearch.durationMs;
  await page.keyboard.press("Escape");

  // Leave Reader for the Library, then wait the gate's 30 s before the heap read.
  // The Frame handles are not kept: every locator here is re-resolved per use, and
  // the waitForFunction handles are disposed in waitFrameChange. What remains is
  // Playwright's InjectedScript in the Frame's own context, which goes with the
  // Frame when Reader unmounts; the runner's control subtracts the rest.
  await runHostCommand(page, "Back to Shelf");
  await goHome(page);
  await page.waitForTimeout(LEAVE_SETTLE_MS);
  const afterLeaveHeapBytes = await heapAfterGc(page);

  const longTasks = await page.evaluate(
    () => (window as unknown as { __readerLongTasks?: unknown[] }).__readerLongTasks ?? []
  );

  writeFileSync(
    resolve(benchOut(), "document.json"),
    `${JSON.stringify(
      {
        iframes,
        baselineHeapBytes,
        afterLeaveHeapBytes,
        leaveSettleMs: LEAVE_SETTLE_MS,
        actions: windows,
        longTasks,
        firstPageMs,
        turnMs,
        searchMs,
      },
      null,
      1
    )}\n`
  );
});
